int dfs(int[][] g, int r, int c) {
    if (r < 0 || c < 0 || r >= g.length || c >= g[0].length) return 0;
    if (g[r][c] == 0) return 0;
    g[r][c] = 0;
    return 1 + dfs(g,r+1,c) + dfs(g,r-1,c) + dfs(g,r,c+1) + dfs(g,r,c-1);
}

void rotate(int[][] m) {
    int n = m.length;
    for (int i = 0; i < n; i++)
        for (int j = i+1; j < n; j++) {
            int t = m[i][j]; m[i][j] = m[j][i]; m[j][i] = t;
        }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n/2; j++) {
            int t = m[i][j]; m[i][j] = m[i][n-1-j]; m[i][n-1-j] = t;
        }
}

boolean canReach(int[] jumps) {
    int far = 0;
    for (int i = 0; i < jumps.length; i++) {
        if (i > far) return false;
        far = Math.max(far, i + jumps[i]);
    }
    return true;
}

