int balance(int[] w) {
    long total = 0;
    for (int x : w) total += x;
    long prefix = 0;
    for (int i = 0; i < w.length; i++) {
        prefix += w[i];
        if (prefix == total - prefix) return i + 1;
    }
    return -1;
}

int maxWindow(int[] d, int k) {
    int sum = 0;
    for (int i = 0; i < k; i++) sum += d[i];
    int best = sum;
    for (int i = k; i < d.length; i++) {
        sum += d[i] - d[i - k];
        best = Math.max(best, sum);
    }
    return best;
}

boolean hasPair(int[] mag, int T) {
    java.util.HashSet<Integer> seen = new java.util.HashSet<>();
    for (int x : mag) {
        if (seen.contains(T - x)) return true;
        seen.add(x);
    }
    return false;
}

int maxBenches(int[] price, long B) {
    java.util.Arrays.sort(price);
    int count = 0;
    for (int p : price) {
        if (B >= p) { B -= p; count++; }
        else break;
    }
    return count;
}

String decompress(String s) {
    StringBuilder sb = new StringBuilder();
    int i = 0, n = s.length();
    while (i < n) {
        char c = s.charAt(i++);
        int count = 0;
        while (i < n && Character.isDigit(s.charAt(i))) {
            count = count * 10 + (s.charAt(i++) - '0');
        }
        if (count == 0) count = 1;
        for (int k = 0; k < count; k++) sb.append(c);
    }
    return sb.toString();
}

int farthest(int n, int[][] edges) {
    java.util.List<java.util.List<Integer>> g = new java.util.ArrayList<>();
    for (int i = 0; i < n; i++) g.add(new java.util.ArrayList<>());
    for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
    int[] dist = new int[n];
    java.util.Arrays.fill(dist, -1);
    java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
    q.add(0); dist[0] = 0;
    int best = 0;
    while (!q.isEmpty()) {
        int u = q.poll();
        for (int v : g.get(u)) if (dist[v] == -1) {
            dist[v] = dist[u] + 1;
            best = Math.max(best, dist[v]);
            q.add(v);
        }
    }
    return best;
}

int tsp(int[][] cost) {
    int n = cost.length;
    int FULL = (1 << n) - 1;
    int[][] dp = new int[1 << n][n];
    final int INF = Integer.MAX_VALUE / 2;
    for (int[] row : dp) java.util.Arrays.fill(row, INF);
    dp[1][0] = 0; // start at node 0
    for (int mask = 1; mask <= FULL; mask++) {
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0 || dp[mask][i] == INF) continue;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0) continue;
                int nm = mask | (1 << j);
                dp[nm][j] = Math.min(dp[nm][j], dp[mask][i] + cost[i][j]);
            }
        }
    }
    int ans = INF;
    for (int i = 1; i < n; i++) ans = Math.min(ans, dp[FULL][i] + cost[i][0]);
    return n == 1 ? 0 : ans;
}

int[] smallestAfterRemoval(int[] h, int k) {
    int n = h.length;
    int[] st = new int[n];
    int top = 0, rem = k;
    for (int x : h) {
        while (top > 0 && st[top - 1] > x && rem > 0) { top--; rem--; }
        st[top++] = x;
    }
    top -= rem; // drop leftover from the end
    return java.util.Arrays.copyOf(st, top);
}

int maxParcels(int[][] grid) {
    int r = grid.length, c = grid[0].length;
    int[][] dp = new int[r][c];
    for (int i = 0; i < r; i++)
        for (int j = 0; j < c; j++) {
            int best = 0;
            if (i > 0) best = Math.max(best, dp[i - 1][j]);
            if (j > 0) best = Math.max(best, dp[i][j - 1]);
            dp[i][j] = grid[i][j] + best;
        }
    return dp[r - 1][c - 1];
}

int maxPieces(int L, int[] cuts) {
    int NEG = Integer.MIN_VALUE / 2;
    int[] dp = new int[L + 1];
    java.util.Arrays.fill(dp, NEG);
    dp[0] = 0;
    for (int x = 1; x <= L; x++)
        for (int c : cuts)
            if (x - c >= 0 && dp[x - c] != NEG)
                dp[x] = Math.max(dp[x], dp[x - c] + 1);
    return dp[L] < 0 ? -1 : dp[L];
}

