int[] twoSumSorted(int[] a, int target) {
    int lo = 0, hi = a.length - 1;
    while (lo < hi) {
        int s = a[lo] + a[hi];
        if (s == target) return new int[]{lo + 1, hi + 1};
        if (s < target) lo++; else hi--;
    }
    return new int[]{-1, -1};
}

