    java.util.Arrays.sort(iv, (x, y) -> Integer.compare(x[1], y[1]));
    int count = 0, lastEnd = Integer.MIN_VALUE;
    for (int[] x : iv) {
        if (x[0] >= lastEnd) { count++; lastEnd = x[1]; }
    }
    return count;
}

