int[] dailyTemperatures(int[] t) {
    int n = t.length;
    int[] res = new int[n];
    java.util.ArrayDeque<Integer> st = new java.util.ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        while (!st.isEmpty() && t[i] > t[st.peek()]) {
            int j = st.pop();
            res[j] = i - j;
        }
        st.push(i);
    }
    return res;
}

