int subarraysWithSum(int[] a, int K) {
    java.util.HashMap<Long, Integer> seen = new java.util.HashMap<>();
    seen.put(0L, 1);
    long prefix = 0; int count = 0;
    for (int x : a) {
        prefix += x;
        count += seen.getOrDefault(prefix - K, 0);
        seen.merge(prefix, 1, Integer::sum);
    }
    return count;
}

